INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'vi', '{"name":"Kẻ Khờ","meaning":"Một hành trình mới đang mở ra. Bạn chưa cần biết hết đường đi để bắt đầu với tâm thế cởi mở. Sự háo hức rất đáng quý, song bạn vẫn cần biết mình có thể học gì từ mỗi bước thử. Lá bài thường xuất hiện khi một lựa chọn mới mời bạn rời khỏi vùng quen thuộc mà không đòi hỏi phải hoàn hảo ngay.","advice":"Hãy thử bước đầu tiên, dù bạn vẫn còn vài điều chưa chắc chắn.","yesNoMeaning":"Chưa có câu trả lời cố định cho khởi đầu này. Kết quả sẽ phụ thuộc vào những bước bạn chọn đi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'vi', '{"name":"Nhà Ảo Thuật","meaning":"Nhà Ảo Thuật gợi khoảnh khắc biến khả năng thành kết quả có thể nhìn thấy. Một ý tưởng sẽ chỉ thành hình khi thời gian, sự chú ý và những nguồn lực bạn đang có cùng hướng về một việc. Nếu đang chờ thêm dấu hiệu, hãy nhìn lại những công cụ đã nằm trong tay mình.","advice":"Chọn một ý tưởng và dùng những gì bạn có để biến nó thành hành động cụ thể.","yesNoMeaning":"Nghiêng về có. Bạn có thể tiến lên nếu tập trung và chủ động dùng khả năng của mình."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'vi', '{"name":"Nữ Tư Tế","meaning":"Có những điều chưa lộ rõ, nhưng trực giác có thể giúp bạn nhận ra. Hãy dành chút yên tĩnh để lắng nghe mình. Sự im lặng ở đây không có nghĩa là không có gì diễn ra. Bạn có thể nhận thấy một mẫu lặp, một cảm giác khó gọi tên hoặc thông tin còn thiếu; hãy quan sát thêm trước khi đưa mọi thứ ra ánh sáng.","advice":"Tạm dừng trước khi quyết định. Để ý cảm giác và những điều bạn đã nhận thấy nhưng chưa gọi thành lời.","yesNoMeaning":"Câu trả lời chưa rõ. Hãy tin vào trực giác và cho mình thêm thời gian trước khi quyết định."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'vi', '{"name":"Hoàng Hậu","meaning":"Một điều quý giá trong đời bạn đang có cơ hội lớn lên nếu được trao đủ thời gian và sự quan tâm. Năng lượng của Hoàng Hậu hiện diện trong cách bạn nuôi dưỡng một mối quan hệ, dự án hoặc chính cơ thể mình. Đủ đầy ở đây là cảm giác có chỗ để phát triển, không phải phải cho đi đến cạn sức.","advice":"Dành thời gian cho người hoặc việc bạn quan tâm, rồi để mọi thứ phát triển theo nhịp tự nhiên.","yesNoMeaning":"Nghiêng về có, nhất là khi bạn tiếp tục chăm sóc và cho điều mình mong muốn thời gian để phát triển."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'vi', '{"name":"Hoàng Đế","meaning":"Sự ổn định đến từ kế hoạch rõ ràng và ranh giới vững chắc. Bạn có thể làm chủ tình hình bằng sự kiên định. Cấu trúc tốt tạo ra chỗ dựa để bạn và người khác yên tâm phát triển. Hãy phân biệt sự dẫn dắt có trách nhiệm với nhu cầu kiểm soát mọi chi tiết, vì hai điều ấy có thể trông rất giống nhau lúc đầu.","advice":"Xác định điều cần ưu tiên, lập kế hoạch và giữ vững những giới hạn quan trọng.","yesNoMeaning":"Nghiêng về có nếu bạn có kế hoạch rõ ràng và kiên trì thực hiện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'vi', '{"name":"Giáo Hoàng","meaning":"Kinh nghiệm và những điều đã được kiểm chứng có thể giúp bạn tìm ra hướng đi đáng tin cậy. Lá bài có thể chỉ một người hướng dẫn, một cộng đồng hoặc phương pháp đã được thử qua thời gian. Học theo khuôn mẫu giúp bạn có nền tảng; hiểu lý do phía sau nó mới giúp bạn dùng đúng hoàn cảnh.","advice":"Học từ người đi trước hoặc hỏi ý kiến người bạn tin tưởng, rồi chọn điều phù hợp với mình.","yesNoMeaning":"Nghiêng về có khi bạn dựa vào kinh nghiệm và lời khuyên đáng tin cậy."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'vi', '{"name":"Đôi Tình Nhân","meaning":"Một mối quan hệ hoặc lựa chọn quan trọng đang cần bạn thành thật với điều mình coi trọng. Sự hòa hợp bền hơn khi hai phía có thể nói thật về mong muốn và giới hạn của mình. Nếu đây là một quyết định chứ không phải chuyện tình cảm, hãy xem lựa chọn nào phản ánh con người bạn muốn trở thành.","advice":"Lắng nghe cả cảm xúc lẫn giá trị của mình. Sự chân thành sẽ giúp bạn kết nối sâu hơn.","yesNoMeaning":"Nghiêng về có khi lựa chọn này phù hợp với tình cảm và điều bạn thật sự coi trọng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'vi', '{"name":"Cỗ Xe","meaning":"Bạn có động lực để tiến lên, nhưng cần giữ hướng đi rõ ràng trước những trở ngại. Hai động lực trái chiều vẫn có thể đưa bạn đi xa khi được giữ chung một hướng. Tiến bộ lúc này đến từ khả năng điều phối cảm xúc và hành động, chứ không chỉ từ việc cố gắng nhiều hơn.","advice":"Tập trung vào mục tiêu và xử lý từng trở ngại một, thay vì để mình bị kéo theo nhiều hướng.","yesNoMeaning":"Nghiêng về có nếu bạn giữ vững mục tiêu và tiếp tục hành động."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'vi', '{"name":"Sức Mạnh","meaning":"Sức mạnh lúc này nằm ở sự bình tĩnh, lòng can đảm và cách bạn đối xử dịu dàng với chính mình. Lá bài gợi sức mạnh mềm: biết ở lại với điều khó chịu mà không để nó quyết định cách mình phản ứng. Bạn có thể vừa thừa nhận nỗi sợ vừa bước tiếp, thay vì chờ đến lúc không còn sợ nữa.","advice":"Đối diện thử thách bằng sự kiên nhẫn. Bạn không cần ép buộc mọi thứ để chứng tỏ mình mạnh mẽ.","yesNoMeaning":"Nghiêng về có nếu bạn kiên trì và giữ bình tĩnh, thay vì cố thúc ép kết quả."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'vi', '{"name":"Ẩn Sĩ","meaning":"Một khoảng lặng có thể giúp bạn hiểu điều mình thật sự cần. Chưa phải lúc vội tìm câu trả lời bên ngoài. Lùi lại một chút giúp tiếng nói của chính bạn rõ hơn giữa quá nhiều ý kiến bên ngoài. Khoảng lặng này có ích khi nó dẫn đến hiểu biết mới, không phải khi bạn dùng nó để tránh mọi kết nối.","advice":"Dành thời gian suy ngẫm và nhìn lại bản thân trước khi quyết định bước tiếp.","yesNoMeaning":"Có lẽ nên chờ thêm. Hãy hiểu rõ mong muốn của mình trước khi hành động."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'vi', '{"name":"Bánh Xe Số Phận","meaning":"Mọi việc đang thay đổi, có thể ngoài dự tính của bạn. Cách bạn thích nghi sẽ quan trọng hơn việc kiểm soát tất cả. Một chu kỳ cũ có thể đang chuyển sang nhịp khác, đem theo cả bất tiện lẫn cơ hội. Bạn không chọn được mọi biến cố, nhưng vẫn có thể chọn điều mình giữ lại và cách chuẩn bị cho vòng tiếp theo.","advice":"Giữ sự linh hoạt và đón nhận cơ hội mới khi tình hình chuyển hướng.","yesNoMeaning":"Chưa thể trả lời chắc chắn. Kết quả còn tùy vào những thay đổi sắp tới và cách bạn ứng phó."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'vi', '{"name":"Công Lý","meaning":"Sự thật, trách nhiệm và công bằng đang được đặt lên bàn cân. Hãy nhìn rõ cả nguyên nhân lẫn hệ quả. Điều đang diễn ra có thể là kết quả của nhiều quyết định trước đó, không chỉ một khoảnh khắc đơn lẻ. Lá bài mời bạn kiểm tra dữ kiện, lắng nghe các bên và nhận phần trách nhiệm thuộc về mình.","advice":"Xem xét các mặt của vấn đề và đưa ra lựa chọn trung thực, công bằng.","yesNoMeaning":"Câu trả lời phụ thuộc vào sự thật và cách bạn hành động. Hãy cân nhắc công bằng trước khi quyết định."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'vi', '{"name":"Người Treo Ngược","meaning":"Tạm dừng có thể giúp bạn nhìn tình huống theo một cách mới. Không phải lúc nào cố tiến lên cũng là tốt nhất. Sự trì hoãn có thể khó chịu, nhất là khi bạn đã quen giải quyết mọi việc bằng hành động. Một góc nhìn đảo chiều hoặc một điều tự nguyện buông xuống có thể mở ra cách hiểu mà sức ép không mang lại.","advice":"Đừng vội thúc ép kết quả. Thử buông một kỳ vọng để thấy điều mình chưa nhận ra.","yesNoMeaning":"Nên chờ thêm. Một góc nhìn mới có thể giúp câu trả lời rõ ràng hơn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'vi', '{"name":"Cái Chết","meaning":"Một giai đoạn đang khép lại để nhường chỗ cho điều mới. Bạn có thể cần buông điều không còn phù hợp. Lá bài nói về kết thúc và chuyển hóa, không nhất thiết là mất mát theo nghĩa đen. Có thể bạn đã lớn hơn một vai trò, thói quen hoặc kỳ vọng cũ; việc rời nó đi cần thời gian để thích nghi.","advice":"Cho phép mình kết thúc việc cũ và dành chỗ cho một khởi đầu khác.","yesNoMeaning":"Con đường hiện tại có thể đang khép lại. Hãy xem điều gì cần kết thúc trước khi chọn hướng mới."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'vi', '{"name":"Tiết Độ","meaning":"Sự cân bằng đến từ kiên nhẫn và biết dung hòa những điều khác biệt. Thay vì chọn một trong hai thái cực, hãy xem phần nào của mỗi bên có thể kết hợp được. Sự tiến triển ở đây thường âm thầm: một thói quen vừa sức, một cuộc trò chuyện bớt căng và nhịp sống có thể duy trì.","advice":"Tiến từng bước vừa sức, điều chỉnh khi cần và giữ nhịp ổn định.","yesNoMeaning":"Nghiêng về có, nhưng hãy kiên nhẫn và tiến từng bước."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'vi', '{"name":"Ác Quỷ","meaning":"Một thói quen, nỗi sợ hoặc sự lệ thuộc có thể đang khiến bạn thấy khó thoát ra. Nhận ra nó là bước đầu để thay đổi. Sợi dây ràng buộc đôi khi là một lợi ích ngắn hạn khiến bạn ngại đối diện cái giá lâu dài. Nhìn rõ điều mình đang nhận được từ thói quen ấy sẽ giúp quyền lựa chọn trở lại, từng bước một.","advice":"Thành thật với điều đang níu giữ mình và tìm một cách nhỏ để lấy lại quyền lựa chọn.","yesNoMeaning":"Nghiêng về không ở thời điểm này. Hãy nhận ra điều đang ràng buộc bạn trước khi tiếp tục."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'vi', '{"name":"Tòa Tháp","meaning":"Một thay đổi bất ngờ có thể làm lung lay điều bạn từng tin là vững chắc. Sự thật lộ ra giúp bạn xây lại từ đầu. Biến động không dễ chịu, nhất là khi nó chạm vào kế hoạch bạn từng đặt nhiều niềm tin. Lá bài không yêu cầu bạn lập tức tìm mặt tích cực; trước hết hãy nhận ra điều gì thực sự đã đổi và điều gì còn đứng vững.","advice":"Cho mình thời gian ổn định sau biến động, rồi xem điều gì cần được xây dựng lại.","yesNoMeaning":"Chưa nên vội tiến lên. Hãy ổn định tình hình trước khi đưa ra quyết định mới."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'vi', '{"name":"Ngôi Sao","meaning":"Sau một giai đoạn khó khăn, hy vọng và cảm hứng đang dần trở lại. Bạn có thể bắt đầu tin vào khả năng hồi phục. Hy vọng trong lá bài này không phải lời hứa rằng mọi việc sẽ tự ổn. Nó giống một khoảng thở sau giông bão, giúp bạn tiếp tục chăm sóc điều có ý nghĩa ngay cả khi kết quả chưa hiện ra.","advice":"Tiếp tục chăm sóc bản thân và nuôi dưỡng điều bạn mong muốn, dù tiến độ còn chậm.","yesNoMeaning":"Nghiêng về có. Hãy tiếp tục nuôi dưỡng hy vọng và cho mọi việc thời gian."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'vi', '{"name":"Mặt Trăng","meaning":"Tình hình còn nhiều điều chưa rõ, và cảm xúc có thể khiến bạn nhìn mọi việc khác đi. Hãy tin trực giác nhưng cũng kiểm chứng điều mình biết. Một câu chuyện chưa đủ dữ kiện rất dễ được lấp đầy bằng suy đoán, ký ức hoặc điều bạn sợ nhất. Lá bài khuyến khích đi chậm, quan sát phản ứng của mình và phân biệt tín hiệu thật với cảm giác nhất thời.","advice":"Đi chậm lại và tìm hiểu thêm trước khi đưa ra kết luận.","yesNoMeaning":"Câu trả lời chưa rõ. Bạn nên tìm thêm thông tin và đợi cảm xúc lắng xuống."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'vi', '{"name":"Mặt Trời","meaning":"Niềm vui, sự rõ ràng và những kết quả tích cực đang đến gần. Bạn có lý do để tự tin với hướng đi của mình. Sự sáng rõ giúp bạn nhìn thấy điều đã tiến bộ và nói về nó mà không phải thu nhỏ niềm vui. Nếu vẫn còn việc cần làm, nguồn năng lượng tích cực này có thể giúp bạn tiếp tục với tinh thần cởi mở hơn.","advice":"Ghi nhận điều tốt đẹp đang có và chia sẻ niềm vui ấy với người khác.","yesNoMeaning":"Nghiêng mạnh về có. Tình hình đang thuận lợi và rõ ràng hơn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'vi', '{"name":"Phán Xét","meaning":"Đã đến lúc nhìn lại, rút kinh nghiệm và quyết định bạn muốn bước tiếp như thế nào. Việc nhìn lại không nhằm tự trách mình mãi về quá khứ. Bạn có thể nhận ra một bài học, tha thứ cho phần đã qua và trả lời lời gọi thay đổi bằng một lựa chọn có ý thức ở hiện tại.","advice":"Thành thật với bản thân, buông những điều đã qua và chọn cách bắt đầu lại.","yesNoMeaning":"Nghiêng về có nếu bạn sẵn sàng nhìn lại quá khứ và thay đổi một cách chân thành."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'vi', '{"name":"Thế Giới","meaning":"Bạn đang đi đến cuối một chặng đường quan trọng. Hãy ghi nhận những gì mình đã hoàn thành trước khi mở ra hành trình mới. Thành quả này không chỉ nằm ở đích đến mà còn ở những kỹ năng, mối quan hệ và góc nhìn bạn mang theo. Lá bài gợi sự trọn vẹn của một vòng trải nghiệm, dù hành trình lớn hơn vẫn tiếp tục.","advice":"Dành chút thời gian trân trọng thành quả, rồi tự tin bước sang giai đoạn tiếp theo.","yesNoMeaning":"Nghiêng về có. Một chặng đường đang khép lại với kết quả trọn vẹn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'vi', '{"name":"Át Gậy","meaning":"Tia cảm hứng mở ra con đường sáng tạo đầy táo bạo. Một lời mời, dự án hoặc mong muốn mới có thể khiến bạn thấy mình sống động hơn. Đây là tiềm năng đang mở ra, chưa phải bảo đảm thành công; nó cần không gian để thử và sự bền bỉ sau phút hào hứng đầu tiên.","advice":"Bắt đầu khi năng lượng còn mới và cho ý tưởng một bước đi cụ thể.","yesNoMeaning":"Át Gậy nghiêng về có: bắt đầu khi năng lượng còn mới và cho ý tưởng một bước đi cụ thể."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'vi', '{"name":"Hai Gậy","meaning":"Tương lai dần thành hình qua việc lập kế hoạch và chọn hướng đi. Bạn đã thấy nhiều hơn một con đường và bắt đầu đo xem mình muốn đi xa đến đâu. Tầm nhìn rộng rất hữu ích, nhưng sự do dự kéo dài có thể giữ bạn ở mãi ngưỡng cửa.","advice":"Nhìn xa hơn điều quen thuộc, rồi cam kết với con đường còn chỗ để phát triển.","yesNoMeaning":"Hai Gậy còn tùy điều kiện: nhìn xa hơn điều quen thuộc, rồi cam kết với con đường còn chỗ để phát triển."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'vi', '{"name":"Ba Gậy","meaning":"Nỗ lực ban đầu mở rộng khi cơ hội và chân trời mới xuất hiện. Điều bạn đã khởi động đang bắt đầu tạo phản hồi ngoài phạm vi quen thuộc. Lá bài gợi giai đoạn quan sát, kết nối và điều chỉnh kỳ vọng khi thành quả cần thêm thời gian để quay về.","advice":"Tiếp tục xây dựng và sẵn sàng đón nhận phản hồi mà công việc mang lại.","yesNoMeaning":"Ba Gậy nghiêng về có: tiếp tục xây dựng và sẵn sàng đón nhận phản hồi mà công việc mang lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'vi', '{"name":"Bốn Gậy","meaning":"Sự ổn định, chào đón và niềm vui chung tạo nên nền tảng vững chắc. Một cột mốc xứng đáng được ăn mừng, dù hành trình chưa kết thúc. Cảm giác thuộc về và những người cùng góp sức tạo ra nền tảng để bạn bước sang chặng kế tiếp vững hơn.","advice":"Ghi nhận cột mốc và chia sẻ niềm vui với những người luôn hỗ trợ bạn.","yesNoMeaning":"Bốn Gậy nghiêng về có: ghi nhận cột mốc và chia sẻ niềm vui với những người luôn hỗ trợ bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'vi', '{"name":"Năm Gậy","meaning":"Những mục tiêu cạnh tranh gây va chạm, ồn ào hoặc thử thách sự tự tin. Nhiều tiếng nói cùng vang lên có thể khiến mục tiêu chung bị che khuất. Va chạm không phải lúc nào cũng xấu; khi mọi người hiểu mình đang tranh luận về điều gì, khác biệt có thể giúp ý tưởng sắc hơn.","advice":"Biến cạnh tranh thành cơ hội rèn luyện và từ chối xung đột vô nghĩa.","yesNoMeaning":"Năm Gậy còn tùy điều kiện: biến cạnh tranh thành cơ hội rèn luyện và từ chối xung đột vô nghĩa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'vi', '{"name":"Sáu Gậy","meaning":"Sự ghi nhận đến sau nỗ lực bền bỉ và tiến bộ rõ ràng. Bạn có thể đang được nhìn nhận vì một việc đã kiên trì làm tốt. Sự công nhận mang lại động lực, nhưng giá trị của nỗ lực vẫn còn đó cả khi không có lời khen hay ánh nhìn của đám đông.","advice":"Đón nhận sự khích lệ, nhưng giữ sự tự tin gắn với công việc chân chính.","yesNoMeaning":"Sáu Gậy nghiêng về có: đón nhận sự khích lệ, nhưng giữ sự tự tin gắn với công việc chân chính."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'vi', '{"name":"Bảy Gậy","meaning":"Bạn đang giữ vị trí có giá trị trong khi áp lực thử thách quyết tâm. Giữ được vị trí hiện tại đòi hỏi bạn biết điều gì đáng bảo vệ. Lá bài nói về áp lực từ nhiều phía, đồng thời nhắc rằng không phải lời thách thức nào cũng cần một cuộc chiến.","advice":"Bảo vệ điều quan trọng bằng ranh giới rõ ràng thay vì đối đầu với mọi thách thức.","yesNoMeaning":"Bảy Gậy nghiêng về có: bảo vệ điều quan trọng bằng ranh giới rõ ràng thay vì đối đầu với mọi thách thức."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'vi', '{"name":"Tám Gậy","meaning":"Sự việc tăng tốc, tin tức đến và đà tiến xóa tan trì hoãn. Tin tức, quyết định hoặc cuộc trao đổi có thể đến nhanh hơn dự kiến. Đà tiến này thuận lợi khi các bên hiểu cùng một hướng; nếu thông tin còn mơ hồ, tốc độ dễ tạo thêm nhầm lẫn.","advice":"Hành động kịp thời và giao tiếp thẳng thắn khi con đường đang rộng mở.","yesNoMeaning":"Tám Gậy nghiêng về có: hành động kịp thời và giao tiếp thẳng thắn khi con đường đang rộng mở."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'vi', '{"name":"Chín Gậy","meaning":"Sức bền vẫn mạnh mẽ, dù căng thẳng trong quá khứ khiến bạn đề phòng. Bạn đã đi qua đủ thử thách để biết cách tự bảo vệ mình, nhưng sự cảnh giác liên tục cũng rất mệt. Đây là lúc đánh giá nguy cơ hiện tại bằng điều đang có trước mắt, thay vì chỉ bằng vết thương cũ.","advice":"Bảo vệ năng lượng và bước tiếp mà không cho rằng mọi tổn thương sẽ lặp lại.","yesNoMeaning":"Chín Gậy còn tùy điều kiện: bảo vệ năng lượng và bước tiếp mà không cho rằng mọi tổn thương sẽ lặp lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'vi', '{"name":"Mười Gậy","meaning":"Trách nhiệm trở nên nặng nề và thành công giờ mang theo gánh nặng. Một điều từng khiến bạn tự hào nay có thể kéo theo quá nhiều đầu việc. Lá bài không phủ nhận năng lực của bạn; nó cho thấy giới hạn của việc ôm mọi trách nhiệm mà không chia sẻ hoặc sắp xếp lại.","advice":"Chia sẻ công việc, đơn giản hóa và đặt xuống những việc không còn thực sự thuộc về bạn.","yesNoMeaning":"Mười Gậy nghiêng về không: chia sẻ công việc, đơn giản hóa và đặt xuống những việc không còn thực sự thuộc về bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'vi', '{"name":"Tiểu Đồng Gậy","meaning":"Sự tò mò mang đến tin tức sôi nổi, thử nghiệm hoặc mối quan tâm sáng tạo mới. Một ý tưởng vừa nhen lên có thể đem đến cảm giác tò mò và háo hức của người mới. Bạn chưa cần biết hết kỹ năng để khám phá, nhưng cần cho bản thân quyền thử, sửa và học từ thực tế.","advice":"Can đảm khám phá và để tinh thần người mới giúp bạn học qua hành động.","yesNoMeaning":"Tiểu Đồng Gậy nghiêng về có: can đảm khám phá và để tinh thần người mới giúp bạn học qua hành động."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'vi', '{"name":"Kỵ Sĩ Gậy","meaning":"Đam mê lao nhanh về phía trước, mang theo phiêu lưu và cả sự nôn nóng. Sức hút của điều mới khiến bạn muốn lên đường ngay lập tức. Năng lượng này mở ra trải nghiệm đáng giá khi có một mục tiêu đủ rõ để bạn không đổi hướng mỗi lần cảm hứng thay đổi.","advice":"Tận dụng đà tiến, nhưng chọn hướng đi trước khi tốc độ làm phân tán nỗ lực.","yesNoMeaning":"Kỵ Sĩ Gậy còn tùy điều kiện: tận dụng đà tiến, nhưng chọn hướng đi trước khi tốc độ làm phân tán nỗ lực."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'vi', '{"name":"Nữ Hoàng Gậy","meaning":"Sự tự tin ấm áp và tinh thần sáng tạo độc lập thu hút người khác đến với tầm nhìn của bạn. Bạn có thể tạo ảnh hưởng bằng sự hiện diện cởi mở và niềm tin vào điều mình làm. Sự tự tin ở đây không đòi hỏi lấn át ai; nó cho phép bạn tỏa sáng đồng thời khuyến khích người khác làm điều tương tự.","advice":"Tin vào sức hiện diện của mình, khích lệ người khác và đừng thu nhỏ hoài bão.","yesNoMeaning":"Nữ Hoàng Gậy nghiêng về có: tin vào sức hiện diện của mình, khích lệ người khác và đừng thu nhỏ hoài bão."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'vi', '{"name":"Vua Gậy","meaning":"Tầm nhìn chín chắn biến cảm hứng thành khả năng lãnh đạo quyết đoán và có đạo đức. Tầm nhìn lớn cần hơn cảm hứng: nó cần quyết định, trách nhiệm và khả năng giữ lửa cho cả một tập thể. Lá bài gợi vai trò dẫn dắt bằng mục đích rõ ràng thay vì chỉ bằng sức ép hoặc cái tôi.","advice":"Dẫn dắt từ mục đích lớn hơn và tạo không gian để người khác đóng góp.","yesNoMeaning":"Vua Gậy nghiêng về có: dẫn dắt từ mục đích lớn hơn và tạo không gian để người khác đóng góp."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'vi', '{"name":"Át Cốc","meaning":"Trái tim mở ra với tình cảm mới, lòng trắc ẩn và sự hồi sinh cảm xúc. Một cuộc gặp, cảm xúc mới hoặc sự dịu lại bên trong có thể khiến bạn muốn trao và nhận nhiều hơn. Chiếc cốc đầy chỉ có ý nghĩa khi cảm xúc được thừa nhận, chứ không phải bị ép vào một kết quả mong muốn.","advice":"Đón nhận cảm xúc chân thành và để sự quan tâm tuôn chảy mà không ép buộc kết quả.","yesNoMeaning":"Át Cốc nghiêng về có: đón nhận cảm xúc chân thành và để sự quan tâm tuôn chảy mà không ép buộc kết quả."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'vi', '{"name":"Hai Cốc","meaning":"Sự thấu hiểu hai chiều tạo nên quan hệ đồng hành, sức hút hoặc đồng thuận chân thành. Điểm quan trọng không chỉ là sự hấp dẫn ban đầu mà là khả năng hai người nhìn thấy nhau rõ hơn. Một cuộc đối thoại có thiện chí, lời xin lỗi hoặc thỏa thuận công bằng có thể đưa mối quan hệ tiến gần hơn.","advice":"Gặp người kia ở vị thế bình đẳng và nói từ trái tim.","yesNoMeaning":"Hai Cốc nghiêng về có: gặp người kia ở vị thế bình đẳng và nói từ trái tim."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'vi', '{"name":"Ba Cốc","meaning":"Tình bạn và cộng đồng mang đến cảm giác được đón nhận. Một cuộc gặp gỡ, bữa mừng nhỏ hoặc sự ủng hộ đúng lúc có thể nhắc bạn rằng niềm vui không cần giữ cho riêng mình. Lá bài cũng gợi sự biết ơn với những người đã ở cạnh bạn cả khi mọi việc chưa thuận lợi.","advice":"Cùng nhau ăn mừng và ghi nhớ ai thực sự có mặt khi bạn cần.","yesNoMeaning":"Ba Cốc nghiêng về có: cùng nhau ăn mừng và ghi nhớ ai thực sự có mặt khi bạn cần."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'vi', '{"name":"Bốn Cốc","meaning":"Sự thu mình về cảm xúc khiến bạn khó nhận ra món quà đang được trao. Khi lòng còn mệt hoặc chán nản, ngay cả một cơ hội tốt cũng có thể trông nhạt nhòa. Lá bài mời bạn thành thật với cảm xúc hiện tại trước khi quyết định rằng mọi thứ xung quanh đều không đáng quan tâm.","advice":"Ngừng so sánh và nhìn lại điều đang được lặng lẽ dành cho bạn.","yesNoMeaning":"Bốn Cốc nghiêng về không: ngừng so sánh và nhìn lại điều đang được lặng lẽ dành cho bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'vi', '{"name":"Năm Cốc","meaning":"Mất mát khiến bạn chú ý tới điều đã đổ vỡ, trong khi điều ý nghĩa vẫn còn. Nỗi buồn cần được công nhận, không phải vội phủ lên bằng suy nghĩ tích cực. Tuy vậy, một mất mát không kể hết toàn bộ câu chuyện; vẫn có thể còn người, cơ hội hoặc nguồn lực đứng cạnh bạn.","advice":"Trân trọng nỗi thất vọng, rồi hướng về sự hỗ trợ vẫn hiện diện.","yesNoMeaning":"Năm Cốc nghiêng về không: trân trọng nỗi thất vọng, rồi hướng về sự hỗ trợ vẫn hiện diện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'vi', '{"name":"Sáu Cốc","meaning":"Ký ức, sự hồn nhiên hoặc mối gắn kết quen thuộc trở lại với hơi ấm dịu dàng. Một kỷ niệm hoặc người quen cũ có thể nhắc bạn về điều từng khiến mình thấy an toàn. Hãy đón nhận sự ấm áp ấy, đồng thời nhận ra hiện tại đã khác và bạn cũng đã thay đổi.","advice":"Đón nhận sự tử tế của quá khứ mà không cho rằng mình phải sống lại trong đó.","yesNoMeaning":"Sáu Cốc nghiêng về có: đón nhận sự tử tế của quá khứ mà không cho rằng mình phải sống lại trong đó."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'vi', '{"name":"Bảy Cốc","meaning":"Nhiều khả năng hấp dẫn làm mờ ranh giới giữa tầm nhìn và ảo tưởng. Mỗi lựa chọn có vẻ mang một lời hứa hấp dẫn, nhưng không phải lời hứa nào cũng có nền tảng như nhau. Lá bài gợi việc phân biệt mong muốn thật với hình ảnh đẹp mà bạn đang tự thêm vào.","advice":"Thu hẹp lựa chọn và đối chiếu một ước mơ với thực tế trước khi cam kết.","yesNoMeaning":"Bảy Cốc chưa rõ câu trả lời: thu hẹp lựa chọn và đối chiếu một ước mơ với thực tế trước khi cam kết."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'vi', '{"name":"Tám Cốc","meaning":"Một tình huống từng ý nghĩa nay không còn nuôi dưỡng trái tim. Rời một nơi từng quan trọng có thể vừa buồn vừa đúng với điều bạn cần lúc này. Lá bài không nói mọi thứ ở đó đều vô giá trị; nó cho thấy nhu cầu tìm kiếm ý nghĩa sâu hơn đã thay đổi.","advice":"Chân thành rời đi và hướng tới sự mãn nguyện sâu sắc hơn mà bạn cần lúc này.","yesNoMeaning":"Tám Cốc nghiêng về không: chân thành rời đi và hướng tới sự mãn nguyện sâu sắc hơn mà bạn cần lúc này."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'vi', '{"name":"Chín Cốc","meaning":"Sự hài lòng và biết ơn khiến một mong ước chân thành trở nên gần gũi. Có thể bạn đã đạt được điều từng mong và xứng đáng tận hưởng cảm giác đủ đầy ấy. Niềm vui sẽ bền hơn khi bạn biết nó đến từ đâu, thay vì lập tức chuyển sang một mong ước mới.","advice":"Tận hưởng hiện tại và tự hỏi mong ước đó có phù hợp với giá trị sâu xa của bạn không.","yesNoMeaning":"Chín Cốc nghiêng về có: tận hưởng hiện tại và tự hỏi mong ước đó có phù hợp với giá trị sâu xa của bạn không."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'vi', '{"name":"Mười Cốc","meaning":"Hòa hợp cảm xúc, cảm giác thuộc về và kết nối bền lâu bao quanh mái ấm. Sự hòa hợp trong lá bài được tạo bởi nhiều lần lắng nghe và quan tâm, không phải một mái ấm không bao giờ bất đồng. Nó gợi cảm giác được là chính mình giữa những người sẵn sàng ở lại và cùng xây dựng.","advice":"Nuôi dưỡng những mối gắn kết giúp niềm vui bền vững và được sẻ chia.","yesNoMeaning":"Mười Cốc nghiêng về có: nuôi dưỡng những mối gắn kết giúp niềm vui bền vững và được sẻ chia."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'vi', '{"name":"Tiểu Đồng Cốc","meaning":"Một thông điệp dịu dàng hoặc khám phá từ trực giác mời bạn mở lòng. Một cảm xúc bất ngờ, lời nhắn dịu dàng hoặc ý tưởng giàu tưởng tượng có thể chạm đến bạn. Hãy dành chỗ cho sự ngạc nhiên mà không vội giải thích hay biến mọi tín hiệu thành lời hứa chắc chắn.","advice":"Tò mò tìm hiểu cảm xúc và đáp lại chân thành thay vì suy đoán.","yesNoMeaning":"Tiểu Đồng Cốc còn tùy điều kiện: tò mò tìm hiểu cảm xúc và đáp lại chân thành thay vì suy đoán."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'vi', '{"name":"Kỵ Sĩ Cốc","meaning":"Sự lãng mạn, trí tưởng tượng hoặc lý tưởng dẫn trái tim về phía trước. Bạn có thể muốn đi theo tiếng gọi của trái tim hoặc một lời mời đầy cảm hứng. Sự chân thành làm hành trình này đẹp hơn, còn tính thực tế giúp bạn nhận ra người và việc nào có thể đi cùng mình lâu dài.","advice":"Đón nhận lời mời, nhưng vẫn thực tế khi những lời hứa dần được thể hiện.","yesNoMeaning":"Kỵ Sĩ Cốc nghiêng về có: đón nhận lời mời, nhưng vẫn thực tế khi những lời hứa dần được thể hiện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'vi', '{"name":"Nữ Hoàng Cốc","meaning":"Sự đồng cảm sâu sắc và trực giác tạo nên không gian bình yên cho sự thật. Lá bài gợi khả năng cảm nhận điều người khác chưa nói ra và tạo không gian để họ được lắng nghe. Sự đồng cảm có chiều sâu khi bạn vẫn biết đâu là nhu cầu của mình, đâu là nỗi buồn mình không thể gánh thay.","advice":"Lắng nghe bằng lòng trắc ẩn, đồng thời giữ ranh giới để sự quan tâm luôn lành mạnh.","yesNoMeaning":"Nữ Hoàng Cốc nghiêng về có: lắng nghe bằng lòng trắc ẩn, đồng thời giữ ranh giới để sự quan tâm luôn lành mạnh."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'vi', '{"name":"Vua Cốc","meaning":"Sự trưởng thành cảm xúc giúp ổn định những cảm giác mạnh mà không đè nén chúng. Cảm xúc mạnh vẫn hiện diện, nhưng bạn có thể chọn cách đáp lại bình tĩnh và có trách nhiệm. Đây là sự vững vàng giúp một cuộc trò chuyện khó trở nên an toàn hơn cho cả hai phía.","advice":"Đáp lại bằng lòng trắc ẩn và sự tự chủ, nhất là khi người khác phản ứng mạnh.","yesNoMeaning":"Vua Cốc nghiêng về có: đáp lại bằng lòng trắc ẩn và sự tự chủ, nhất là khi người khác phản ứng mạnh."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'vi', '{"name":"Át Kiếm","meaning":"Một nhận thức sáng rõ xuyên qua bối rối và hé lộ sự thật mới. Một câu nói, thông tin mới hoặc khoảnh khắc tự nhận ra có thể làm vấn đề sáng tỏ. Sự thật đôi khi sắc bén, vì thế điều quan trọng là dùng nó để hiểu và quyết định rõ hơn, không phải để làm tổn thương.","advice":"Gọi tên vấn đề thẳng thắn và dùng sự sáng rõ để đưa ra quyết định công bằng.","yesNoMeaning":"Át Kiếm nghiêng về có: gọi tên vấn đề thẳng thắn và dùng sự sáng rõ để đưa ra quyết định công bằng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'vi', '{"name":"Hai Kiếm","meaning":"Thế bế tắc đầy phòng thủ trì hoãn một lựa chọn không thể treo mãi. Bạn có thể đang giữ thế cân bằng bằng cách chưa chọn bên nào, dù áp lực vẫn còn đó. Sự bình tĩnh là cần thiết, nhưng né nhìn thông tin khó chịu sẽ không khiến quyết định tự biến mất.","advice":"Nhẹ nhàng tháo bỏ tấm che mắt, tìm dữ kiện còn thiếu và quyết định trong cân bằng.","yesNoMeaning":"Hai Kiếm chưa rõ câu trả lời: nhẹ nhàng tháo bỏ tấm che mắt, tìm dữ kiện còn thiếu và quyết định trong cân bằng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'vi', '{"name":"Ba Kiếm","meaning":"Một sự thật đau lòng, chia ly hoặc thất vọng cần được thừa nhận. Một lời nói, sự chia xa hoặc kỳ vọng đổ vỡ có thể để lại cảm giác nhói đau. Lá bài cho phép bạn gọi tên tổn thương và tìm người hỗ trợ, thay vì vội chứng tỏ rằng mình đã ổn.","advice":"Để cảm xúc đi qua và đừng biến tổn thương thành câu chuyện vĩnh viễn về mình.","yesNoMeaning":"Ba Kiếm nghiêng về không: để cảm xúc đi qua và đừng biến tổn thương thành câu chuyện vĩnh viễn về mình."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'vi', '{"name":"Bốn Kiếm","meaning":"Bạn cần nghỉ ngơi và tĩnh tâm sau áp lực hoặc xung đột. Sau một thời gian phải phản ứng liên tục, tâm trí cần khoảng nghỉ để sắp xếp lại. Tạm dừng ở đây là một phần của quá trình hồi phục và chuẩn bị, không phải dấu hiệu bạn đã bỏ cuộc.","advice":"Tạm dừng trước khi trả lời. Hồi phục có giá trị khi giúp suy nghĩ sáng rõ trở lại.","yesNoMeaning":"Bốn Kiếm nghiêng về không: tạm dừng trước khi trả lời. Hồi phục có giá trị khi giúp suy nghĩ sáng rõ trở lại."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'vi', '{"name":"Năm Kiếm","meaning":"Xung đột có thể tạo ra chiến thắng rỗng tuếch hoặc làm tổn hại niềm tin. Có những tranh cãi mà giành phần đúng vẫn khiến quan hệ xấu đi hoặc chính bạn kiệt sức. Lá bài đặt câu hỏi về cái giá của chiến thắng và ranh giới cần có để giữ lòng tự trọng.","advice":"Chọn phẩm giá thay vì thắng thua và rời xa những cách làm có cái giá quá đắt.","yesNoMeaning":"Năm Kiếm nghiêng về không: chọn phẩm giá thay vì thắng thua và rời xa những cách làm có cái giá quá đắt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'vi', '{"name":"Sáu Kiếm","meaning":"Một chặng đường khó khăn đang dần dẫn tới điều kiện bình yên hơn. Sự chuyển tiếp có thể diễn ra lặng lẽ: rời một cuộc đối thoại bế tắc, một môi trường cũ hoặc cách nghĩ từng làm bạn mệt. Bạn chưa cần thấy nơi đến hoàn hảo để biết mình đang đi về phía bình yên hơn.","advice":"Mang theo bài học, đón nhận hỗ trợ và tiếp tục rời xa hỗn loạn.","yesNoMeaning":"Sáu Kiếm nghiêng về có: mang theo bài học, đón nhận hỗ trợ và tiếp tục rời xa hỗn loạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'vi', '{"name":"Bảy Kiếm","meaning":"Chiến lược, bí mật hoặc né tránh khiến con đường phức tạp hơn. Giữ kín kế hoạch đôi khi là cách tự bảo vệ, nhưng né tránh trách nhiệm lại tạo ra khoảng cách và nghi ngờ. Lá bài mời bạn nhìn rõ động cơ phía sau một chiến lược trước khi quyết định dùng nó.","advice":"Hành động khéo léo nhưng minh bạch. Lối tắt phản bội niềm tin sẽ trở lại thành rắc rối.","yesNoMeaning":"Bảy Kiếm nghiêng về không: hành động khéo léo nhưng minh bạch. Lối tắt phản bội niềm tin sẽ trở lại thành rắc rối."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'vi', '{"name":"Tám Kiếm","meaning":"Nỗi sợ và niềm tin giới hạn khiến bạn khó nhìn thấy những lựa chọn sẵn có. Cảm giác bị vây kín có thể lớn hơn những giới hạn thực tế trước mặt. Khi lo sợ giảm bớt, bạn có thể nhìn thấy một bước nhỏ, một người hỗ trợ hoặc một lựa chọn mình từng bỏ qua.","advice":"Chất vấn suy nghĩ rằng mình bị mắc kẹt và thực hiện một hành động nhỏ để tự giải phóng.","yesNoMeaning":"Tám Kiếm nghiêng về không: chất vấn suy nghĩ rằng mình bị mắc kẹt và thực hiện một hành động nhỏ để tự giải phóng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'vi', '{"name":"Chín Kiếm","meaning":"Lo âu phóng đại nguy cơ trong bóng tối và làm tâm trí kiệt sức. Những suy nghĩ lặp đi lặp lại thường dữ dội nhất khi bạn chỉ ở một mình với chúng. Lá bài gợi việc tách điều đã xảy ra khỏi điều bạn đang tưởng tượng, và cho phép mình tìm sự giúp đỡ khi cần.","advice":"Đưa nỗi sợ ra ánh sáng, tìm hỗ trợ và phân biệt sự thật với kết quả do mình tưởng tượng.","yesNoMeaning":"Chín Kiếm nghiêng về không: đưa nỗi sợ ra ánh sáng, tìm hỗ trợ và phân biệt sự thật với kết quả do mình tưởng tượng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'vi', '{"name":"Mười Kiếm","meaning":"Một chu kỳ đau đớn chạm giới hạn cuối cùng và không thể tiếp tục như cũ. Kết thúc này có thể khiến bạn thấy mất hết sức lực, nhất là khi đã cố kéo dài một tình huống quá lâu. Điều cũ không thể giữ nguyên, nhưng ranh giới rõ ràng sẽ tạo chỗ cho sự hồi phục từng bước.","advice":"Chấp nhận kết thúc, bảo vệ quá trình hồi phục và để một khởi đầu khác xuất hiện.","yesNoMeaning":"Mười Kiếm nghiêng về không: chấp nhận kết thúc, bảo vệ quá trình hồi phục và để một khởi đầu khác xuất hiện."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'vi', '{"name":"Tiểu Đồng Kiếm","meaning":"Sự tò mò tỉnh táo tìm kiếm dữ kiện, đặt câu hỏi và theo dõi thay đổi. Sự tò mò khiến bạn muốn đặt câu hỏi và kiểm tra từng chi tiết trước khi tin vào kết luận. Năng lượng này rất hữu ích cho việc học hỏi, miễn là bạn không biến sự cảnh giác thành nghi ngờ tất cả mọi người.","advice":"Nghiên cứu cẩn thận và nói chính xác thay vì phản ứng với mọi tín hiệu.","yesNoMeaning":"Tiểu Đồng Kiếm còn tùy điều kiện: nghiên cứu cẩn thận và nói chính xác thay vì phản ứng với mọi tín hiệu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'vi', '{"name":"Kỵ Sĩ Kiếm","meaning":"Trí tuệ tập trung chuyển động nhanh và đối diện trực tiếp với trở ngại. Một ý tưởng hoặc mục tiêu rõ ràng có thể khiến bạn lao về phía trước và nói điều mình nghĩ không vòng vo. Sự quyết liệt có ích khi bạn vẫn nghe được dữ kiện mới và tác động lời nói lên người khác.","advice":"Can đảm tiến lên, nhưng đủ chậm để nghe điều mà sự chắc chắn của bạn có thể bỏ sót.","yesNoMeaning":"Kỵ Sĩ Kiếm còn tùy điều kiện: can đảm tiến lên, nhưng đủ chậm để nghe điều mà sự chắc chắn của bạn có thể bỏ sót."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'vi', '{"name":"Nữ Hoàng Kiếm","meaning":"Nhận thức rõ ràng và ranh giới chân thành cắt bỏ sự bối rối. Kinh nghiệm giúp bạn nhận ra điều gì thật sự quan trọng giữa nhiều cảm xúc và lời hứa. Lá bài gợi sự thẳng thắn có ranh giới: rõ ràng trong phán đoán nhưng không cần đánh mất lòng trắc ẩn.","advice":"Nói sự thật với lòng trắc ẩn và để kinh nghiệm làm bạn sắc sảo, không chai sạn.","yesNoMeaning":"Nữ Hoàng Kiếm nghiêng về có: nói sự thật với lòng trắc ẩn và để kinh nghiệm làm bạn sắc sảo, không chai sạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'vi', '{"name":"Vua Kiếm","meaning":"Lý trí, công bằng và phán đoán có kỷ luật dẫn dắt một quyết định quan trọng. Một quyết định khó cần tiêu chuẩn nhất quán, lập luận sáng rõ và khả năng tách sự việc khỏi thiên kiến cá nhân. Quyền lực của lá bài nằm ở sự công tâm, không chỉ ở việc nói lời cuối cùng.","advice":"Dựa vào bằng chứng, xác định tiêu chuẩn và gạt thiên kiến cá nhân khỏi phán đoán.","yesNoMeaning":"Vua Kiếm nghiêng về có: dựa vào bằng chứng, xác định tiêu chuẩn và gạt thiên kiến cá nhân khỏi phán đoán."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'vi', '{"name":"Át Tiền","meaning":"Một cơ hội cụ thể gieo hạt cho sự đủ đầy, công việc hoặc sức khỏe tinh thần và thể chất. Cơ hội có thể đến dưới dạng một việc làm, khoản hỗ trợ, kỹ năng mới hoặc điều kiện sống tốt hơn. Giá trị của nó còn nằm ở khả năng được nuôi dưỡng từng ngày, chứ không chỉ ở vẻ hấp dẫn ban đầu.","advice":"Đặt cơ hội vào kế hoạch thực tế và chăm sóc nó đều đặn.","yesNoMeaning":"Át Tiền nghiêng về có: đặt cơ hội vào kế hoạch thực tế và chăm sóc nó đều đặn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'vi', '{"name":"Hai Tiền","meaning":"Nhiều ưu tiên chuyển động cùng lúc và đòi hỏi sự cân bằng linh hoạt. Bạn có thể đang xoay xở giữa công việc, thời gian, tiền bạc và nhu cầu riêng. Sự linh hoạt giúp mọi thứ tiếp tục vận hành, nhưng nếu nhịp này kéo dài, điều gì thiết yếu sẽ cần được ưu tiên rõ hơn.","advice":"Điều chỉnh nhịp độ, giữ điều thiết yếu và đừng hứa quá khả năng gánh vác.","yesNoMeaning":"Hai Tiền còn tùy điều kiện: điều chỉnh nhịp độ, giữ điều thiết yếu và đừng hứa quá khả năng gánh vác."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'vi', '{"name":"Ba Tiền","meaning":"Kỹ năng phát triển qua hợp tác, phản hồi và sự trau chuốt cẩn thận. Một kết quả tốt được tạo nên khi mỗi người hiểu phần việc và thế mạnh của mình. Lá bài gợi giá trị của học nghề, phản hồi cụ thể và sự tôn trọng dành cho công sức thường không nổi bật.","advice":"Đóng góp thế mạnh, tôn trọng chuyên môn và cùng xây dựng theo tiêu chuẩn chung.","yesNoMeaning":"Ba Tiền nghiêng về có: đóng góp thế mạnh, tôn trọng chuyên môn và cùng xây dựng theo tiêu chuẩn chung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'vi', '{"name":"Bốn Tiền","meaning":"Bám chặt vào sự an toàn có thể giữ nguồn lực nhưng hạn chế dòng chảy lành mạnh. Giữ lại thứ mình đã vất vả có được là phản ứng dễ hiểu trước bất ổn. Tuy nhiên, khi nỗi sợ mất mát quyết định mọi việc, cả tiền bạc lẫn sự an tâm đều có thể trở nên chật chội.","advice":"Bảo vệ điều quan trọng mà không để nỗi sợ quyết định mọi thứ thay bạn.","yesNoMeaning":"Bốn Tiền còn tùy điều kiện: bảo vệ điều quan trọng mà không để nỗi sợ quyết định mọi thứ thay bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'vi', '{"name":"Năm Tiền","meaning":"Khó khăn vật chất hoặc cảm giác bị gạt ra ngoài gây lo lắng và thiếu thốn. Thiếu thốn dễ khiến bạn cảm thấy mình phải chịu đựng một mình hoặc không xứng đáng được giúp. Lá bài nhắc rằng sự hỗ trợ thực tế có thể vẫn ở gần, dù lúc khó khăn bạn chưa nhìn thấy lối vào.","advice":"Tìm sự giúp đỡ thiết thực và chú ý cánh cửa mà nghịch cảnh khiến bạn dễ bỏ qua.","yesNoMeaning":"Năm Tiền nghiêng về không: tìm sự giúp đỡ thiết thực và chú ý cánh cửa mà nghịch cảnh khiến bạn dễ bỏ qua."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'vi', '{"name":"Sáu Tiền","meaning":"Sự trao đổi nguồn lực đặt ra câu hỏi về rộng lượng, quyền lực và công bằng. Sự giúp đỡ có ý nghĩa khi cả người cho lẫn người nhận đều giữ được tiếng nói và phẩm giá. Lá bài mời bạn xem một trao đổi có cân bằng không, và điều kiện nào đang đi kèm với lòng tốt.","advice":"Cho hoặc nhận với thỏa thuận rõ ràng để sự hỗ trợ giữ được phẩm giá của cả hai bên.","yesNoMeaning":"Sáu Tiền nghiêng về có: cho hoặc nhận với thỏa thuận rõ ràng để sự hỗ trợ giữ được phẩm giá của cả hai bên."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'vi', '{"name":"Bảy Tiền","meaning":"Đầu tư kiên nhẫn đến lúc cần đánh giá trước đợt nỗ lực tiếp theo. Bạn đã bỏ công vun trồng nhưng chưa chắc kết quả xuất hiện đúng lúc mong đợi. Đây là thời điểm nhìn lại tiến độ, phân biệt việc cần kiên nhẫn với việc cần đổi cách làm.","advice":"Xem điều gì đang phát triển, cải thiện cách làm và cho kết quả xứng đáng đủ thời gian.","yesNoMeaning":"Bảy Tiền còn tùy điều kiện: xem điều gì đang phát triển, cải thiện cách làm và cho kết quả xứng đáng đủ thời gian."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'vi', '{"name":"Tám Tiền","meaning":"Luyện tập tập trung và lặp lại tạo nên sự thành thạo cùng kết quả đáng tin. Sự thành thạo hình thành từ những lần làm lại, sửa lỗi và chú ý đến chi tiết nhỏ. Lá bài không hứa một bước nhảy nhanh; nó cho thấy giá trị của quá trình đều đặn mà người ngoài ít nhìn thấy.","advice":"Rèn kỹ năng cốt lõi, đón nhận sửa sai và để chất lượng tích lũy dần.","yesNoMeaning":"Tám Tiền nghiêng về có: rèn kỹ năng cốt lõi, đón nhận sửa sai và để chất lượng tích lũy dần."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'vi', '{"name":"Chín Tiền","meaning":"Tự chủ và sự thoải mái được vun đắp phản ánh tiến bộ có kỷ luật. Khoảng thoải mái hiện tại có thể là thành quả của nhiều lựa chọn kỷ luật trước đó. Tự chủ cho phép bạn tận hưởng điều đẹp đẽ theo nhịp của mình, đồng thời biết rõ công sức đã tạo nên nó.","advice":"Tận hưởng điều đã xây dựng và giữ sự độc lập gắn với lòng biết ơn.","yesNoMeaning":"Chín Tiền nghiêng về có: tận hưởng điều đã xây dựng và giữ sự độc lập gắn với lòng biết ơn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'vi', '{"name":"Mười Tiền","meaning":"An toàn lâu dài phát triển từ di sản, gia đình và nền tảng chung. Câu chuyện vượt khỏi lợi ích của một người: điều bạn xây dựng có thể ảnh hưởng đến gia đình, cộng đồng hoặc những người đến sau. Lá bài gợi nền tảng bền vững được tạo từ sự chăm lo có kế hoạch.","advice":"Lập kế hoạch vượt khỏi thắng lợi trước mắt và bảo vệ điều có thể nâng đỡ người khác lâu dài.","yesNoMeaning":"Mười Tiền nghiêng về có: lập kế hoạch vượt khỏi thắng lợi trước mắt và bảo vệ điều có thể nâng đỡ người khác lâu dài."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'vi', '{"name":"Tiểu Đồng Tiền","meaning":"Một thông điệp thiết thực mời bạn học hỏi, lập kế hoạch hoặc bắt đầu dự án vững vàng. Một cơ hội thực tế sẽ sáng rõ hơn khi bạn chịu khó học những bước căn bản. Tò mò ở đây đi cùng sự kiên trì: tìm hiểu, thử trong phạm vi nhỏ rồi quan sát điều nào thật sự có giá trị.","advice":"Học nền tảng, xác định việc tiếp theo và kiểm chứng ý tưởng bằng công việc bền bỉ.","yesNoMeaning":"Tiểu Đồng Tiền nghiêng về có: học nền tảng, xác định việc tiếp theo và kiểm chứng ý tưởng bằng công việc bền bỉ."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'vi', '{"name":"Kỵ Sĩ Tiền","meaning":"Nỗ lực đáng tin tiến chậm nhưng hiếm khi bỏ dở nhiệm vụ. Nhịp tiến có thể chậm đến mức bạn nghi ngờ mình đang đi đâu, nhưng sự nhất quán đang xây nền. Lá bài gợi người biết giữ lời và hoàn thành việc cần làm, đồng thời cần nhớ dành chỗ cho nghỉ ngơi.","advice":"Giữ thói quen chân chính và nhất quán. Tiến bộ quan trọng hơn cảm giác hào hứng.","yesNoMeaning":"Kỵ Sĩ Tiền nghiêng về có: giữ thói quen chân chính và nhất quán. Tiến bộ quan trọng hơn cảm giác hào hứng."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'vi', '{"name":"Nữ Hoàng Tiền","meaning":"Sự chăm sóc khéo léo tạo ra tiện nghi, sức khỏe và sự đủ đầy thiết thực. Bạn có thể tạo cảm giác an toàn bằng những việc rất cụ thể: chăm sóc, sắp xếp nguồn lực và chú ý nhu cầu hằng ngày. Sự hào phóng bền vững bắt đầu từ việc không bỏ quên chính mình.","advice":"Nuôi dưỡng con người và kế hoạch theo cách vẫn bền vững với chính bạn.","yesNoMeaning":"Nữ Hoàng Tiền nghiêng về có: nuôi dưỡng con người và kế hoạch theo cách vẫn bền vững với chính bạn."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'vi', '{"name":"Vua Tiền","meaning":"Kinh nghiệm và khả năng quản lý nguồn lực đang tạo ra một nền tảng đáng tin cậy. Lá bài gợi cách chăm lo lâu dài cho công việc, gia đình hoặc cộng đồng mà không đánh đổi mọi thứ để tích lũy. Thành công có ý nghĩa hơn khi những người cùng xây dựng cũng được hưởng sự ổn định ấy.","advice":"Đưa ra lựa chọn dài hạn vững chắc và sử dụng thành công một cách có trách nhiệm.","yesNoMeaning":"Vua Tiền nghiêng về có: đưa ra lựa chọn dài hạn vững chắc và sử dụng thành công một cách có trách nhiệm."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'vi', '{"name":"Bạch Dương","dateRange":"21/3 – 19/4","rulingPlanet":"Sao Hỏa","summary":"Bạch Dương thích bắt đầu và không ngại hành động. Sự thẳng thắn giúp cung này biến ý tưởng thành bước đi cụ thể.","originStory":"Bạch Dương gắn với con cừu vàng đã cứu Phrixus trong thần thoại Hy Lạp. Bộ lông của nó sau này trở thành báu vật mà Jason và đoàn Argonaut tìm kiếm, lưu giữ hình ảnh cung này như biểu tượng của lòng can đảm, sự cứu giúp và bước đi dũng cảm đầu tiên.","traits":["Can đảm","Năng động","Độc lập","Thẳng thắn"],"strengths":["Chủ động","Tự tin","Bền bỉ"],"challenges":["Thiếu kiên nhẫn","Bốc đồng","Khởi đầu nhanh hơn khả năng duy trì"],"compatibleSigns":["Sư Tử","Nhân Mã","Song Tử"],"reflectionPrompt":"Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bạch Dương mang năng lượng Lửa. Bạch Dương thích bắt đầu và không ngại hành động. Sự thẳng thắn giúp cung này biến ý tưởng thành bước đi cụ thể.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bạch Dương mang năng lượng Lửa. Bạch Dương thích bắt đầu và không ngại hành động. Sự thẳng thắn giúp cung này biến ý tưởng thành bước đi cụ thể.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bạch Dương mang năng lượng Lửa. Bạch Dương thích bắt đầu và không ngại hành động. Sự thẳng thắn giúp cung này biến ý tưởng thành bước đi cụ thể.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh chủ động, tự tin, bền bỉ giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng can đảm, năng động, độc lập, thẳng thắn làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi thiếu kiên nhẫn, bốc đồng, khởi đầu nhanh hơn khả năng duy trì bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng.","guidance":"Trở lại định hướng này trong suốt năm: Hãy bắt đầu điều bạn muốn làm, rồi kiên nhẫn theo đuổi đến cùng."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'vi', '{"name":"Kim Ngưu","dateRange":"20/4 – 20/5","rulingPlanet":"Sao Kim","summary":"Kim Ngưu coi trọng sự ổn định và những điều có thể cảm nhận được. Sự kiên nhẫn giúp cung này xây dựng giá trị lâu dài.","originStory":"Kim Ngưu gợi nhắc Zeus hóa thành con bò trắng tuyệt đẹp để đưa Europa vượt biển. Hình ảnh này gắn với vẻ đẹp, sự sinh sôi, đủ đầy nơi trần thế và sức mạnh được thể hiện qua sự kiên trì điềm tĩnh.","traits":["Thực tế","Trung thành","Kiên nhẫn","Giàu cảm nhận"],"strengths":["Đáng tin","Khôn ngoan thực tế","Tận tâm"],"challenges":["Cứng đầu","Ngại thay đổi","Níu giữ quá lâu"],"compatibleSigns":["Xử Nữ","Ma Kết","Cự Giải"],"reflectionPrompt":"Giữ lấy điều quan trọng với bạn, nhưng đừng ngại thay đổi khi cần."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Kim Ngưu mang năng lượng Đất. Kim Ngưu coi trọng sự ổn định và những điều có thể cảm nhận được. Sự kiên nhẫn giúp cung này xây dựng giá trị lâu dài.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đáng tin, khôn ngoan thực tế, tận tâm giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng thực tế, trung thành, kiên nhẫn, giàu cảm nhận làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cứng đầu, ngại thay đổi, níu giữ quá lâu bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Giữ lấy điều quan trọng với bạn, nhưng đừng ngại thay đổi khi cần.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Giữ lấy điều quan trọng với bạn, nhưng đừng ngại thay đổi khi cần."}');
