INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'vi', '{"name":"Xử Nữ","dateRange":"23/8 – 22/9","rulingPlanet":"Sao Thủy","summary":"Xử Nữ quan sát kỹ và muốn mọi việc tốt hơn. Cung này thường biến sự tỉ mỉ thành những thay đổi thiết thực.","originStory":"Xử Nữ thường gắn với Astraea, thiếu nữ công lý ở lại với loài người sau khi các vị thần khác rời đi. Bông lúa nàng mang liên hệ cung này với mùa gặt, kỹ năng, ý định trong sáng và việc chăm nom những gì duy trì sự sống.","traits":["Tinh ý","Thực tế","Chu đáo","Chính xác"],"strengths":["Phân tích","Tay nghề","Hỗ trợ hữu ích"],"challenges":["Cầu toàn","Tự phê bình","Lo lắng về tiểu tiết"],"compatibleSigns":["Kim Ngưu","Ma Kết","Cự Giải"],"reflectionPrompt":"Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Xử Nữ mang năng lượng Đất. Xử Nữ quan sát kỹ và muốn mọi việc tốt hơn. Cung này thường biến sự tỉ mỉ thành những thay đổi thiết thực.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh phân tích, tay nghề, hỗ trợ hữu ích giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tinh ý, thực tế, chu đáo, chính xác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cầu toàn, tự phê bình, lo lắng về tiểu tiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Xử Nữ mang năng lượng Đất. Xử Nữ quan sát kỹ và muốn mọi việc tốt hơn. Cung này thường biến sự tỉ mỉ thành những thay đổi thiết thực.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh phân tích, tay nghề, hỗ trợ hữu ích giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng tinh ý, thực tế, chu đáo, chính xác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi cầu toàn, tự phê bình, lo lắng về tiểu tiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Xử Nữ mang năng lượng Đất. Xử Nữ quan sát kỹ và muốn mọi việc tốt hơn. Cung này thường biến sự tỉ mỉ thành những thay đổi thiết thực.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh phân tích, tay nghề, hỗ trợ hữu ích giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng tinh ý, thực tế, chu đáo, chính xác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi cầu toàn, tự phê bình, lo lắng về tiểu tiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo.","guidance":"Trở lại định hướng này trong suốt năm: Làm tốt điều trong tầm tay, rồi cho phép mình dừng lại trước khi mọi thứ hoàn hảo."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'vi', '{"name":"Thiên Bình","dateRange":"23/9 – 22/10","rulingPlanet":"Sao Kim","summary":"Thiên Bình coi trọng sự hài hòa và công bằng, luôn cố gắng lắng nghe nhiều phía trước khi lựa chọn.","originStory":"Cán cân của Thiên Bình được nữ thần công lý Astraea cầm trên tay, là biểu tượng vô tri duy nhất trong vòng Hoàng đạo. Nó đại diện cho phán đoán có cân nhắc, hòa hợp xã hội và nỗ lực liên tục khôi phục cân bằng thay vì mặc định cân bằng đã có sẵn.","traits":["Ngoại giao","Công tâm","Duyên dáng","Hợp tác"],"strengths":["Hòa giải","Đa chiều","Tạo hòa hợp"],"challenges":["Do dự","Chiều lòng người khác","Né tránh xung đột cần thiết"],"compatibleSigns":["Song Tử","Bảo Bình","Sư Tử"],"reflectionPrompt":"Lắng nghe người khác, nhưng cũng đừng quên nói ra điều mình cần."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Thiên Bình mang năng lượng Khí. Thiên Bình coi trọng sự hài hòa và công bằng, luôn cố gắng lắng nghe nhiều phía trước khi lựa chọn.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh hòa giải, đa chiều, tạo hòa hợp giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ngoại giao, công tâm, duyên dáng, hợp tác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi do dự, chiều lòng người khác, né tránh xung đột cần thiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Lắng nghe người khác, nhưng cũng đừng quên nói ra điều mình cần.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Lắng nghe người khác, nhưng cũng đừng quên nói ra điều mình cần."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Thiên Bình mang năng lượng Khí. Thiên Bình coi trọng sự hài hòa và công bằng, luôn cố gắng lắng nghe nhiều phía trước khi lựa chọn.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh hòa giải, đa chiều, tạo hòa hợp giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng ngoại giao, công tâm, duyên dáng, hợp tác làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi do dự, chiều lòng người khác, né tránh xung đột cần thiết bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Lắng nghe người khác, nhưng cũng đừng quên nói ra điều mình cần.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Lắng nghe người khác, nhưng cũng đừng quên nói ra điều mình cần."}');
