INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'vi', '{"name":"Bọ Cạp","dateRange":"23/10 – 21/11","rulingPlanet":"Sao Diêm Vương","summary":"Bọ Cạp nhìn sâu vào cảm xúc và không ngại đối diện sự thật, kể cả khi điều đó dẫn đến thay đổi.","originStory":"Bọ Cạp gợi nhắc con bọ cạp được gửi đến đối đầu thợ săn Orion sau khi lòng kiêu hãnh của chàng làm đảo lộn trật tự tự nhiên. Vị trí đối nhau trên bầu trời gợi về ranh giới, hệ quả, điều bí ẩn và sức tái sinh sau một kết thúc.","traits":["Mãnh liệt","Sâu sắc","Trung thành","Tháo vát"],"strengths":["Can đảm với cảm xúc","Tập trung","Chuyển hóa"],"challenges":["Giữ kín","Nghi ngờ","Giữ lòng oán giận"],"compatibleSigns":["Cự Giải","Song Ngư","Xử Nữ"],"reflectionPrompt":"Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bọ Cạp mang năng lượng Nước. Bọ Cạp nhìn sâu vào cảm xúc và không ngại đối diện sự thật, kể cả khi điều đó dẫn đến thay đổi.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bọ Cạp mang năng lượng Nước. Bọ Cạp nhìn sâu vào cảm xúc và không ngại đối diện sự thật, kể cả khi điều đó dẫn đến thay đổi.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bọ Cạp mang năng lượng Nước. Bọ Cạp nhìn sâu vào cảm xúc và không ngại đối diện sự thật, kể cả khi điều đó dẫn đến thay đổi.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh can đảm với cảm xúc, tập trung, chuyển hóa giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng mãnh liệt, sâu sắc, trung thành, tháo vát làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi giữ kín, nghi ngờ, giữ lòng oán giận bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng.","guidance":"Trở lại định hướng này trong suốt năm: Hãy dùng sự thấu hiểu để thay đổi điều cần thay đổi, thay vì giữ mọi chuyện trong lòng."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'vi', '{"name":"Nhân Mã","dateRange":"22/11 – 21/12","rulingPlanet":"Sao Mộc","summary":"Nhân Mã ham học hỏi, thích khám phá và luôn tìm kiếm một góc nhìn rộng hơn về cuộc sống.","originStory":"Nhân Mã thường được liên hệ với Chiron, nhân mã thông thái và người thầy có mũi tên hướng vượt khỏi điều quen thuộc. Chòm sao tượng trưng cho sự kết hợp giữa bản năng và hiểu biết cao hơn, luôn hướng tới chân trời có ý nghĩa hơn.","traits":["Ưa khám phá","Lạc quan","Thẳng thắn","Thích triết lý"],"strengths":["Tầm nhìn","Nhiệt huyết","Cởi mở"],"challenges":["Thẳng quá mức","Hứa quá khả năng","Trốn tránh nề nếp"],"compatibleSigns":["Bạch Dương","Sư Tử","Bảo Bình"],"reflectionPrompt":"Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Nhân Mã mang năng lượng Lửa. Nhân Mã ham học hỏi, thích khám phá và luôn tìm kiếm một góc nhìn rộng hơn về cuộc sống.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh tầm nhìn, nhiệt huyết, cởi mở giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng ưa khám phá, lạc quan, thẳng thắn, thích triết lý làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi thẳng quá mức, hứa quá khả năng, trốn tránh nề nếp bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Nhân Mã mang năng lượng Lửa. Nhân Mã ham học hỏi, thích khám phá và luôn tìm kiếm một góc nhìn rộng hơn về cuộc sống.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh tầm nhìn, nhiệt huyết, cởi mở giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng ưa khám phá, lạc quan, thẳng thắn, thích triết lý làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi thẳng quá mức, hứa quá khả năng, trốn tránh nề nếp bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Nhân Mã mang năng lượng Lửa. Nhân Mã ham học hỏi, thích khám phá và luôn tìm kiếm một góc nhìn rộng hơn về cuộc sống.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh tầm nhìn, nhiệt huyết, cởi mở giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng ưa khám phá, lạc quan, thẳng thắn, thích triết lý làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi thẳng quá mức, hứa quá khả năng, trốn tránh nề nếp bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay.","guidance":"Trở lại định hướng này trong suốt năm: Cứ đặt mục tiêu xa, nhưng hãy bắt đầu bằng những việc bạn có thể làm hôm nay."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'vi', '{"name":"Ma Kết","dateRange":"22/12 – 19/1","rulingPlanet":"Sao Thổ","summary":"Ma Kết kiên trì và biết tính đường dài. Cung này sẵn sàng đi từng bước để đạt mục tiêu mình coi trọng.","originStory":"Dê biển Ma Kết gắn với Pan, người hóa một phần cơ thể thành cá khi trốn Typhon. Bản chất núi và biển kết hợp hoài bão với khả năng sinh tồn cảm xúc, trân trọng sự thành thạo được tích lũy qua thời gian và trách nhiệm.","traits":["Tham vọng","Kỷ luật","Kiên nhẫn","Trách nhiệm"],"strengths":["Sức bền","Chiến lược","Đáng tin cậy"],"challenges":["Cứng nhắc","Bi quan","Đo giá trị bản thân bằng thành tích"],"compatibleSigns":["Kim Ngưu","Xử Nữ","Bọ Cạp"],"reflectionPrompt":"Tiếp tục xây dựng điều lâu dài, và nhớ dành thời gian nghỉ ngơi."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Ma Kết mang năng lượng Đất. Ma Kết kiên trì và biết tính đường dài. Cung này sẵn sàng đi từng bước để đạt mục tiêu mình coi trọng.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh sức bền, chiến lược, đáng tin cậy giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng tham vọng, kỷ luật, kiên nhẫn, trách nhiệm làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi cứng nhắc, bi quan, đo giá trị bản thân bằng thành tích bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Tiếp tục xây dựng điều lâu dài, và nhớ dành thời gian nghỉ ngơi.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Tiếp tục xây dựng điều lâu dài, và nhớ dành thời gian nghỉ ngơi."}');
